         (P SS n SBL SBH S4 L4 pt PTR BITS PP OL : Z) (w240 w248 : word),
    PTR = S4 + pt ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S4 ->
