(* [comment removed for export] *)
Definition w4s34_D4_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x7 x8 x9 x10 x12 x13 x15 x17 x18 x19 x20 x21 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
         (P DT4 DBL DBH DST dcap tl PP BW C : Z) (cells : list deltX1) (obuf : list Z) (w248 : word),
    w4s1_dctx RNG mm P DT4 DBL DBH DST dcap tl ->
    mem_inv asegs mm ->
    x1_table_ok cells tl ->
    bytes_at asegs mm DT4 (firstn (Z.to_nat (2 * 2^tl)) (x1_bytes cells)) ->
    u8arr asegs mm DST (map (Z_to_bv 8) obuf) ->
    zlen obuf = dcap ->
    rw_cells asegs mm (P + 240) [C8 (Z_to_bv 64 C)] ->
    rw_cells asegs mm (P + 248) [C4 w248] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    DST <= PP ->
    PP + 4 <= DST + dcap ->
    0 <= BW <= 7 ->
    0 <= C < 2^64 ->
    (forall (mm' : amem) (B' : Z) (y6 y7 y14 y28 y29 y30 y31 : word),
       munch [(DST, DST + dcap); (P + 248, P + 252)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
       rw_cells asegs mm' (P + 248) [C4 (Z_to_bv 64 B')] ->
       0 <= B' <= 55 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (64 - tl)) y6 y7 x8 x9 x10 (Z_to_bv 64 (PP + 4)) x12 x13
           y14 (Z_to_bv 64 B') (Z_to_bv 64 (PP + 4)) x17 x18 x19 x20 x21 (Z_to_bv 64 DT4) x23 x24 x25 x26 x27 y28 y29
           y30 y31) F (Z_to_bv 64 0x92bac) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (64 - tl)) (Z_to_bv 64 BW) x7 x8 x9 x10 (Z_to_bv 64 PP)
        x12 x13 (Z_to_bv 64 C) x15 (Z_to_bv 64 PP) x17 x18 x19 x20 x21 (Z_to_bv 64 DT4) x23 x24 x25 x26 x27 x28 x29
        x30 x31) F (Z_to_bv 64 0x92a1c) fc None mm (seg_rom asegs)).

